examples.css:
body { font-family: sans-serif; background: #f8fafc; padding: 16px; }
.row { display: flex; gap: 28px; align-items: center; }
.box { padding: 20px; background: #fff; border-radius: 12px; box-shadow: 0 1px 2px #0003, 0 12px 24px #0002; }
.glow { width: 70px; height: 70px; border-radius: 50%; background: rgb(174,68,90); box-shadow: 0 0 30px 12px #ffb000; display: grid; place-items: center; color: #fff; }
.shape { width: 0; height: 0; border-left: 40px solid transparent; border-right: 40px solid transparent; border-bottom: 70px solid #2965f1; filter: drop-shadow(6px 8px 6px rgba(0,0,0,.4)); }
.neon { color: #fff; background: #111; padding: 10px; text-shadow: 0 0 6px #0ff, 0 0 14px #0ff, 0 0 28px #08f; }

.g { display: flex; flex-wrap: wrap; gap: 8px; font: 12px sans-serif; color: #fff; }
i { width: 90px; height: 90px; display: grid; place-items: center; font-style: normal; border-radius: 10px; background: linear-gradient(135deg,#f06,#fc0,#0cf); transition: filter .3s; }
.b { filter: grayscale(1); }
.c { filter: blur(3px); }
.d { filter: hue-rotate(120deg); }
.e { filter: sepia(.8) contrast(1.3); }
i:hover { filter: none; }

body { display: flex; gap: 8px; font-family: sans-serif; }
.t { width: 100px; height: 100px; display: grid; place-items: center; color: #fff; font-size: 13px;
  background-color: #ff3368;
  background-image: repeating-linear-gradient(45deg, #1e90ff 0 12px, #ffd700 12px 24px); }
.multiply { background-blend-mode: multiply; }
.screen { background-blend-mode: screen; }
.overlay { background-blend-mode: overlay; }
.diff { background-blend-mode: difference; }

.s { display: flex; gap: 12px; flex-wrap: wrap; }
i { width: 90px; height: 90px; background: linear-gradient(135deg,#6a11cb,#2575fc); }
.tri { clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.oct { clip-path: polygon(20% 0,80% 0,100% 20%,100% 80%,80% 100%,20% 100%,0 80%,0 20%); }
.arr { clip-path: polygon(40% 0,40% 20%,100% 20%,100% 80%,40% 80%,40% 100%,0 50%); }
.cir { clip-path: circle(50%); }
.star { clip-path: polygon(50% 0,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%); background: gold; }

.r { width: 160px; height: 160px; display: grid; place-items: center; color: #fff; font: bold 16px sans-serif; background: #e11d48;
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%); transition: clip-path .5s; }
.r:hover { clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%); }

.scene { padding: 28px; background: radial-gradient(circle at 20% 20%, #ff0080, transparent 40%), radial-gradient(circle at 80% 70%, #00dfd8, transparent 45%), #4b1d8f; border-radius: 14px; font-family: sans-serif; }
.glass { max-width: 240px; padding: 18px; color: #fff; background: rgba(255,255,255,.15); backdrop-filter: blur(12px) saturate(150%); -webkit-backdrop-filter: blur(12px) saturate(150%); border: 1px solid rgba(255,255,255,.35); border-radius: 16px; box-shadow: 0 8px 32px rgba(0,0,0,.25); }
h3 { margin: 0 0 6px; }
p { margin: 0; font-size: 14px; }

.surface { background: #e0e5ec; padding: 30px; display: flex; gap: 24px; border-radius: 16px; }
.neu { border: 0; padding: 14px 28px; border-radius: 16px; background: #e0e5ec; color: #4a5568; font: bold 16px sans-serif; cursor: pointer;
  box-shadow: 8px 8px 14px #a3b1c6, -8px -8px 14px #fff; transition: box-shadow .15s; }
.neu:active { box-shadow: inset 6px 6px 10px #a3b1c6, inset -6px -6px 10px #fff; }
.round { border-radius: 50%; width: 56px; height: 56px; padding: 0; }
